from collections import defaultdict

def longest_common_prefix(text1, text2):
    prefix_len = 0
    n, m = len(text1), len(text2)
    while prefix_len < min(n, m):
        if text1[prefix_len] == text2[prefix_len]:
            prefix_len += 1
        else:
            break
    return prefix_len

def solution():
    n, k = map(int, input().split())
    proteins = [input() for _ in range(n)]

    proteins.sort(key=lambda x: len(x))

    types = defaultdict(list)
    for protein in proteins:
        types[len(protein)].append(protein)

    scores = []
    for prefix_length in range(1, 51):
        j = 0
        for protein in types[prefix_length]:
            if j >= k:
                break
            prefix_token = proteins[j]
            score = 0
            prefix_len = 1
            while prefix_len < len(prefix_token):
                score += longest_common_prefix(protein, prefix_token)
                prefix_len += 1
            else:
                if j + 1 < k:
                    prefix_token = proteins[j + 1]
                    while protein != prefix_token:
                        score += 50
                        prefix_token = proteins[j + 1]
                        j += 1
                j += 1
            if j == k:
                scores.append(score)
            elif j < k and prefix_token not in proteins[j + 1:]:
                scores.append(score + 36)

    return max(scores)

