def are_friendly(sequences: List[int]) -> bool:
    """Check if all sequences are suitable and not uniquely divisible."""
    for p in sequences:
        divided_nums = set()
        for q in sequences:
            if p != q and p % q == 0:
                divided_nums.add(q)
    return len(divided_nums) == len(sequences) - 1

def find_ideal_sequence(x: int, n: int, k: int) -> List[int]:
    """Find a suitable and friendly sequence for x."""
    primes = set([p for p in range(2, x) if all(p % d != 0 for d in primes)])
    for k_ideal in range(1, n+1):
        if are_friendly([x]*k_ideal) and are_friendly([a for a in x if a not in primes] + list(primes)):
            return [a for a in x if a not in primes]
    return []

