from heapq import heappush, heappop

def rotate(point, angle):
    angle = math.radians(angle)
    x, y = point
    cx, cy = (0.5, 0.5)
    x1 = x - cx
    y1 = y - cy
    x2 = x1 * math.cos(angle) - y1 * math.sin(angle)
    y2 = x1 * math.sin(angle) + y1 * math.cos(angle)
    return (x2 + cx, y2 + cy)

def extend(point, distance):
    return (point[0] + distance, point[1])

def process_line(line):
    action, y, z = line
    if action == 1:
        yield extend((0, 0), y)
    else:
        my, mz = rotate((1, 0), z)
        yield my
        yield mz

def calculate_endpoints(line_x, line_y, base_x, base_y):
    endpoints = []
    for action, distance, rotation in line_x + line_y:
        endpoint = extend((base_x, base_y), distance)
        endpoint = rotate(endpoint, rotation)
        endpoints.append(endpoint)
    return endpoints

