def is_surface_connected(N, costed):
    graph = defaultdict(list)
    for a, b, c in costed:
        graph[a].append((b, c))
        graph[b].append((a, c))

    Q = deque([0, 1])
    seen = set([0])
    distance = [float('inf')] * N
    distance[0], distance[1] = 0, 0

    while Q:
        u = Q.popleft()
        for v, w in graph[u]:
            if v not in seen:
                seen.add(v)
                distance[v] = distance[u] + w
                Q.append(v)

    return distance

def calculate_min_cost(N, Q, costed, surface_obj):
