def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_ideal_sequence(x, k):
    def is_friendable(P):
        seen = set()
        for p in P:
            if p in seen:
                return False
            seen.add(p)
        return True

    def backtracking(index, sequence):
        if index == k:
            if is_friendable(sequence):
                print(" ".join(map(str, sequence)))
            return
        for x_val in x:
            if not seen[x_val]:
                sequence.append(x_val)
                seen[x_val] = True
                backtracking(index + 1, sequence)
                seen[x_val] = False  # backtrack

    n = len(x)
    if n < k * 2:
        print("0")
        return

    x.sort()
    k = min(k, n)

    seq = [x[0]]  # Starting from the smallest prime
    seen = {x[0]: True}  # Marking the smallest prime as used to avoid duplicates

    for i in range(1, k):
        while not is_prime(seq[-1]):
            seq = [x[i]]  # Resetting the sequence once we find a non-prime
            seen = {x[i]: True}  # Resetting the usage flag
            for j in range(i + 1, min(i + 4, k - 1)):
                seq.append(x[j])
                seen[x[j]] = True
                if len(seq) == k:
                    print(" ".join(map(str, seq)))
                    return
    print("0")

