                            if (is_in_range(k, l, r, n, m) and abs(k - i) + abs(l - j) != max(j_radius + i_radius, max(j_radius + i_radius, 2 * (r - i_radius - j_radius + i - k)))):
                                curr_sum -= sum(table[k])
                                break
            if curr_sum > max_sum:
                max_sum = curr_sum
                max_pairs = 1
            elif curr_sum == max_sum:
