        k = min(6, j - 2)
        for m in range(1, k + 1):
            for g in range(1, j + 1):
                l = g // m * j + 2 * m * (g % m - 1)
                for p in primes[:j - 2 + m * (g % m - 1)]:
                    d = lcm(p, g)
                    dp[l * d] += dp[k * d] * pow(d, mod - 2, mod)
