from math import gcd

def find_special_ratio(nums):
    ''' finds a ratio with factorials (scale factor multiplying distribution) 
    for each number in nums 
    '''
    scale_factor = 1
    special_ratio = Counter()

    for num in nums:
        # Respect Sieve of Eratosthenes
        if num < 2:
            continue
        factor = 2
        while num % factor == 0:
            # Multiply largest factor
            special_ratio[factor] += 1
            num //= factor
        if num > 1:
            # Largest remaining factor
            special_ratio[num] += 1

    return special_ratio, scale_factor

def accept_ratio(count_dict, scale_factor):
    special_ratio, cnt_diff = count_dict, 0
    del count_dict[2]

    # Use factorials to calculate acceptance rule
    #  2^c[2], 3^c[3], 5^c[5], ...
    for prime, degree in special_ratio.items():
        accept = True
        max_degree = 1 << (cnt_diff + 1)
        for i in range(len(special_ratio) - 1, -1, -1):
            if cnt_diff >= i and power := gcd(max_degree, prime ** (degree + 1)) > 1:
                accept = False
                break
            elif power < 1 << i + 1:
                break
        if accept:
            cnt_diff += 1
            if cnt_diff > special_ratio[2]:
                break
            for factor, degree in special_ratio.items():
                if degree < max_degree := 1 << (cnt_diff + 1): 
                    # Since scale factor to total is squared factor
                    # don't apply any more
                    scale_factor *= factor ** (degree + 1)
                    cnt_diff += degree + 1
                else: 
                    if cnt_diff + degree + 1 > special_ratio[2]: 
                        break
                    else:
                        scale_factor *= factor ** (cnt_diff + degree + 1)
                        cnt_diff += degree + 1

    return int(scale_factor), cnt_diff

