from collections import defaultdict

def get_visible_area(i, j, size):
    seen = set()
    seen.add((i, j))

    r, c = size
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for x, y in directions:
        i0, j0 = i + x * r, j + y * r
        while 0 <= i0 < n and 0 <= j0 < m and (i0, j0) not in seen:
            seen.add((i0, j0))
            i0, j0 = i0 + x * r, j0 + y * r

    return len(seen)

def solve(grid):
    n, m, r = len(grid), len(grid[0]), grid[0][0]

    max_sum = 0
    best_pairs = 0

    for i in range(n):
        for j in range(m):
            if (i + r) < n and (j + r) < m:
                for size in range(r + 1, 2**16):
                    visible_areas = []
                    for x in range(-size + 1, size):
                        for y in range(-size + 1, size):
                            if (0 <= i + x < n and 0 <= j + y < m):
                                area = get_visible_area(i + x, j + y, size)
                                visible_areas.append((i + x, j + y, area))

                    if area else -1):
                        sum_ = 0
                        for x, y, area in visible_areas:
                            sum_ += grid[x][y] * area

                        if sum_ > max_sum:
                            max_sum = sum_
                            best_pairs = 1
                        elif sum_ == max_sum:
                            best_pairs += 1

    if max_sum < 2**16:
        return max_sum, best_pairs
    else:
        return 0, 0

