from collections import defaultdict
from typing import List

def longest_common_prefix(s1: str, s2: str) -> int:
    min_length = min(len(s1), len(s2))
    for i in range(min_length):
        if s1[i] != s2[i]:
            return i
    return min_length

def max_representativity(k: int, proteins: List[str]) -> int:
    representativity = defaultdict(int)
    representativity[0] = 0
    for protein in proteins:
        prefix = ""
        for i in range(1, len(protein) + 1):
            candidate_prefix = protein[:i]
            if any(longest_common_prefix(candidate_prefix, other) > len(prefix) for other in proteins):
                representativity[i] = len(protein)
                break
            else:
                prefix = candidate_prefix

    return max(representativity[i] for i in range(1, k+1))

# Example usage:
n, k = map(int, input().split())
